from wcommon import legend, notes, head, sched
from disc_ceil import _grid
LAYER = "A-FLOOR"
def _z(s,r,t,pat=None,color=8,sc=1.0,tc=7):
    x0,y0,x1,y1=r
    if pat: s.hatch([(x0,y0),(x1,y0),(x1,y1),(x0,y1)],pattern=pat,scale=sc,color=color)
    s.label((x0+x1)/2,(y0+y1)/2,t,h=0.11,color=tc)
def _tiles(s,r,w,h):
    x0,y0,x1,y1=r; x=x0
    while x<x1: s.line((x,y0),(x,y1),color=8,lw=5); x+=w
    y=y0
    while y<y1: s.line((x0,y),(x1,y),color=8,lw=5); y+=h
ROWS=[(lambda s,x,y: _tiles(s,(x-0.3,y-0.15,x+0.3,y+0.15),0.2,0.1), "بورسلان رصاصي مطفي 120×60 سم (الصالة والجلسات والمكاتب)", "matte grey porcelain 120x60"),
      (lambda s,x,y: _tiles(s,(x-0.3,y-0.15,x+0.3,y+0.15),0.15,0.15), "بلاط رصاصي مانع للانزلاق R11 60×60 سم (المطبخ والحمامات)", "anti-slip grey tile 60x60 R11"),
      (lambda s,x,y: s.hatch([(x-0.3,y-0.12),(x+0.3,y-0.12),(x+0.3,y+0.12),(x-0.3,y+0.12)],pattern="ANSI31",scale=0.25,color=1), "بورسلان أحمر لامع 60×60 (منطقة الدرج والمدخل - حسب الرندر)", "red glossy porcelain 60x60"),
      (lambda s,x,y: s.line((x-0.3,y),(x+0.3,y),color=7,lw=50), "وزرة بورسلان 10 سم بنفس البلاط", "porcelain skirting 10 cm")]
