    s.hatch([(9.3,35.1),(14.4,35.1),(14.4,36.4),(9.3,36.4)],pattern="ANSI31",scale=0.25,color=1); s.hatch([(9.3,36.4),(10.4,36.4),(10.4,43.6),(9.3,43.6)],pattern="ANSI31",scale=0.25,color=1)
    s.label(11.85,35.75,"بورسلان أحمر لامع 60×60 - شريط المدخل والدرج",h=0.1,color=7)
